installer-gui-script.script:
function pm_install_check() {
    var arm = system.sysctl('hw.optional.arm64');
    if (arm == '0') {
        my.result.title = 'Not an Apple Silicon Mac';
        my.result.message = 'This installer replaces the Intel-only Native Instruments driver with the arm64 driver. Use “Traktor Kontrol S4 2.8.0 Installer Mac.pkg” on an Intel Mac instead.';
        my.result.type = 'Fatal';
        return false;
    }
    if (!(system.compareVersions(system.version.ProductVersion, '11.0') >= 0)) {
        my.result.title = 'macOS 11 or later required';
        my.result.message = 'This driver requires macOS 11 Big Sur or later on Apple Silicon.';
        my.result.type = 'Fatal';
        return false;
    }
    return true;
}
